from collections import Counter

def field_accuracy(preds, gts):
    total = hit = 0
    for p, g in zip(preds, gts):
        for k in g:
            total += 1
            hit += (p.get(k) == g[k])
    return hit / total

def confusion_pairs(preds, gts, topn=3):
    c = Counter()
    for p, g in zip(preds, gts):
        for a in g:
            if p.get(a) == g[a]:
                continue
            for b in g:                      # 找「A 的真值跑到了哪个字段上」
                if b != a and p.get(b) == g[a]:
                    c[(a, b)] += 1
                    break
    return c.most_common(topn)

# 验证：构造销方/购方互串的系统性错误（此处以「销方名称/备注」示意）
gts = [{"发票号": "A1", "金额": "100", "销方名称": "甲公司", "备注": "-"} for _ in range(4)]
preds = [{"发票号": "A1", "金额": "100", "销方名称": "-", "备注": "甲公司"} for _ in range(4)]
print(f"字段级准确率={field_accuracy(preds, gts):.2%}")
print("Top混淆对:", confusion_pairs(preds, gts))
